try (ExecutorService pool = Executors.newFixedThreadPool(4)) {
    List<Future<Integer>> futures = new ArrayList<>();
    for (int n = 1; n <= 10; n++) {
        int k = n;
        futures.add(pool.submit(() -> k * k));
    }
    int total = 0;
    for (Future<Integer> f : futures) {
        total += f.get();   // must handle InterruptedException and ExecutionException
    }
    System.out.println("sum of squares 1..10 = " + total);
}   // close(): shutdown, then wait for every task

