static void stop(ExecutorService pool, Duration grace) {
    pool.shutdown();                                        // no new tasks
    try {
        if (!pool.awaitTermination(grace.toMillis(), TimeUnit.MILLISECONDS)) {
            pool.shutdownNow();                             // interrupt what is still running
            if (!pool.awaitTermination(5, TimeUnit.SECONDS)) {
                System.err.println("pool did not terminate");
            }
        }
    } catch (InterruptedException e) {
        pool.shutdownNow();
        Thread.currentThread().interrupt();                 // keep the flag for the caller
    }
}

